"""Admission/evidence regression scenarios, preserving review and first-run failures."""
import json

import pytest

from core.context_namespace import ensure_chat_namespace
from tests.test_fresh_acceptance_memrepair2b_20260927 import _inject, _store, fresh_profile

CASES = json.loads('[{"id": "Q01", "lane": "plain purchase", "docs": [["I spent 74 euros on the Aster field recorder yesterday.", ""]], "query": "What did I spend on the Aster field recorder?", "need": ["74", "Aster field recorder"]}, {"id": "Q02", "lane": "plain concrete fact", "docs": [["The observatory cabinet contains 16 spare filters.", ""]], "query": "How many spare filters are in the observatory cabinet?", "need": ["16 spare filters"]}, {"id": "Q03", "lane": "marked concrete fact", "docs": [["Session date: 2026/08/14\\nUSER: The observatory cabinet contains 16 spare filters.", ""]], "query": "How many spare filters are in the observatory cabinet?", "need": ["16 spare filters"]}, {"id": "Q04", "lane": "question is not assertion", "docs": [["Should I spend 180 euros on a new pottery wheel?", ""]], "query": "How much did I spend on my pottery wheel?", "skip": true, "empty": true}, {"id": "Q05", "lane": "ownership question", "docs": [["Does my neighbour own a green canoe?", ""]], "query": "What colour is my neighbour\'s canoe?", "skip": true, "empty": true}, {"id": "Q06", "lane": "real assistant parameter", "docs": [["Thanks for the suggestions, I\'ll think about them.", "You should buy the Helios telescope for 320 euros."]], "query": "Which telescope did I buy?", "forbid": ["Helios"], "empty": true}, {"id": "Q07", "lane": "transcript actual choice", "docs": [["Session date: 2026/08/19\\nUSER: Remember that I booked the Willow marsh walk for 45 euros.\\nASSISTANT: You might instead book the Amber canyon walk for 110 euros.", ""]], "query": "Which walk did I book and what did it cost?", "need": ["Willow marsh walk for 45"], "forbid": ["Amber canyon"]}, {"id": "Q08", "lane": "multiline suggestion", "docs": [["Session date: 2026/08/20\\nUSER: Remember that I have not bought any telescope.\\nASSISTANT: A strong telescope choice is\\nHelios Meridian, priced at 320 euros.", ""]], "query": "Which telescope did I buy?", "need": ["not bought any telescope"], "forbid": ["Helios Meridian"]}, {"id": "Q09", "lane": "stated date versus ingest order", "docs": [["Session date: 2026/08/23\\nUSER: Remember my seed cabinet now holds 11 packets.", ""], ["Session date: 2026/07/10\\nUSER: Remember my seed cabinet now holds 6 packets.", ""]], "query": "How many packets does my seed cabinet hold now?", "need": ["11 packets"], "order": ["11 packets", "6 packets"]}, {"id": "Q10", "lane": "confirmation preserves fact", "docs": [["Remember the rehearsal room walls are violet.", ""]], "query": "Are the rehearsal room walls violet?", "need": ["rehearsal room walls are violet"]}, {"id": "Q11", "lane": "cross-chat isolation", "docs": [["Remember my delivery locker code is Birch-462.", ""]], "query": "What is my delivery locker code?", "query_chat": "other-chat", "empty": true, "forbid": ["Birch-462"]}, {"id": "Q12", "lane": "plain purchase proper noun", "docs": [["I bought the Wren Alto microscope last Saturday.", ""]], "query": "Which microscope did I buy?", "need": ["Wren Alto microscope"]}, {"id": "Q13", "lane": "filler control", "docs": [["Wonderful, thanks for walking me through that!", ""]], "query": "Which bike did I buy?", "skip": true, "empty": true}, {"id": "Q14", "lane": "conditional assertion", "docs": [["Remember: when the kiln alarm sounds, the studio door must stay closed.", ""]], "query": "When the kiln alarm sounds, must the studio door stay closed?", "need": ["kiln alarm sounds", "studio door must stay closed"]}, {"id": "F01", "lane": "unpriced acquisition", "docs": [["I ordered the Larch Ridge binoculars last Tuesday.", ""]], "query": "Which binoculars did I order?", "need": ["Larch Ridge binoculars"]}, {"id": "F02", "lane": "unmarked state", "docs": [["The station cabinet contains 19 replacement fuses.", ""]], "query": "How many replacement fuses are in the station cabinet?", "need": ["19 replacement fuses"]}, {"id": "F03", "lane": "price question", "docs": [["Should I pay 290 euros for a folding kayak?", ""]], "query": "How much did I pay for the folding kayak?", "skip": true, "empty": true}, {"id": "F04", "lane": "third party question", "docs": [["Does my colleague keep a yellow terrarium?", ""]], "query": "What colour is my colleague\'s terrarium?", "skip": true, "empty": true}, {"id": "F05", "lane": "mixed asserted plus question", "docs": [["I purchased the Juniper Trail tent on Monday. Should I buy a 450 euro stove?", ""]], "query": "Which tent did I purchase?", "need": ["Juniper Trail tent"], "forbid": ["450 euro"]}, {"id": "F06", "lane": "conditional preservation", "docs": [["Remember: if the pressure drops, the gallery valve must remain shut.", ""]], "query": "If the pressure drops, what must happen to the gallery valve?", "need": ["pressure drops", "gallery valve must remain shut"]}, {"id": "F07", "lane": "marker no authority", "docs": [["Session date: 2026/09/01\\nUSER: Should I buy a 750 euro bassoon?", ""]], "query": "How much did I spend on my bassoon?", "skip": true, "empty": true}, {"id": "F08", "lane": "negation preservation", "docs": [["Remember I have not bought the Copper Arc camera.", ""]], "query": "Did I buy the Copper Arc camera?", "need": ["not bought the Copper Arc camera"]}]')
@pytest.mark.parametrize("case", CASES, ids=lambda c:c["id"])
def test_assertion_workflow(fresh_profile,case):
    statuses=[_store(fresh_profile,"source-chat",u) for u,a in case["docs"]]
    ensure_chat_namespace(case.get("query_chat","source-chat"),grant_current_receipts=False)
    block=_inject(fresh_profile,case.get("query_chat","source-chat"),case["query"])
    # mr29 evidence contract: admission gates still refuse INDEXING these
    # (stored_count 0), but the source statement is now RETAINED at layer 1
    # ("retained") instead of being dropped entirely ("skipped").
    if case.get("skip"): assert all(s["status"] in ("skipped","retained") and s["stored_count"]==0 for s in statuses)
    if case.get("empty"): assert not block
    for needle in case.get("need",[]): assert needle.casefold() in block.casefold()
    for needle in case.get("forbid",[]): assert needle.casefold() not in block.casefold()
    if case.get("order"):
        new,old=case["order"]
        assert new in block and (old not in block or block.index(new)<block.index(old))
